          "type": "string",
          "enum": [
            "assistant"
          ]
        }
      }
    },
    {
      "type": "object",
      "$ref": "agent.completions.message.ToolMessageExpression",
      "properties": {
        "role": {
          "type": "string",
          "enum": [
            "tool"
          ]
        }
      }
    }
  ]
}

